CREATE TABLE ezcontentobject_tree (node_id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, contentobject_id INTEGER DEFAULT NULL, contentobject_is_published INTEGER DEFAULT NULL, contentobject_version INTEGER DEFAULT NULL, depth INTEGER DEFAULT 0 NOT NULL, is_hidden INTEGER DEFAULT 0 NOT NULL, is_invisible INTEGER DEFAULT 0 NOT NULL, main_node_id INTEGER DEFAULT NULL, modified_subnode INTEGER DEFAULT 0, parent_node_id INTEGER DEFAULT 0 NOT NULL, path_identification_string CLOB DEFAULT NULL, path_string VARCHAR(255) DEFAULT '' NOT NULL, priority INTEGER DEFAULT 0 NOT NULL, remote_id VARCHAR(100) DEFAULT '' NOT NULL, sort_field INTEGER DEFAULT 1, sort_order INTEGER DEFAULT 1);
